class SocialNetwork:
    homophily_strength: float = 0.0
    homophily_labels: Optional[List[int]] = None
    ...
    def connect_agents(self, N: int) -> List[List[int]]:
        if self.topology == "scale_free":
            self.adj = self._scale_free(N, max(1, self.average_degree // 2))
        else:
            self.adj = self._small_world(N, self.average_degree, self.rewiring_prob)
        return self.adj

    def _scale_free(self, N: int, m: int) -> List[List[int]]:
        # Barabási–Albert attachment with optional homophily bias
        adj = [set() for _ in range(N)]
        # seed a small clique
        for i in range(m + 1):
            for j in range(i + 1, m + 1):
                adj[i].add(j); adj[j].add(i)
        targets = [j for i in range(m + 1) for j in adj[i]]
        for i in range(m + 1, N):
            chosen = set()
            while len(chosen) < m and targets:
                cand = self.rng.choice(targets)
                # homophily bias: prefer same-label neighbors
                if self.homophily_labels is not None and self.rng.random() < self.homophily_strength:
                    same = [t for t in targets if self.homophily_labels[t] == self.homophily_labels[i % len(self.homophily_labels)]]
                    if same:
                        cand = self.rng.choice(same)
                if cand != i and cand not in chosen:
                    chosen.add(cand)
            for c in chosen:
                adj[i].add(c); adj[c].add(i)
            targets.extend(list(chosen)); targets.extend([i] * len(chosen))
        return [list(nei) for nei in adj]

